head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[linkedDataList > M > getAllFilteredJSON]<br/>필터/정렬이 적용된 상태를 기준으로 Row 의 데이터를 JSON 형식의 객체 배열로 반환합니다.",
    "validation" : [
        "'Filter Condition' 이 적용된 상태를 기준으로 동작합니다.",
        "반환값으로 Row 의 상태값에 관계없이 전체 Row 의 데이터를 JSON 형식의 객체 배열로 반환합니다.",
        "setColumnFilter() 메소드로 필터링 되지 않은 경우 전체 Row 데이터를 JSON 형식의 객체 배열로 반환합니다.",
        "반환된 객체의 json 속성값으로 LinkedDataList 모듈에 링크된 전체 Column ID 를 Key 로 'Column ID:Value' 형태의 Key-Value 쌍으로 구성됩니다.",
        "마지막 Key 는 'rowStatus' 로 Row 의 상태값을 갖습니다.",
        "원본 DataLIst 모듈이 rowNumData=true 인 경우 반환값의 마지막 Key 로 'rowNum' 이 추가되고 Row 의 순번(인덱스+1)값을 갖습니다.",
    ]
}



scwin.onpageload = function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // comp 초기 생성
    scwin.comp_init();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// comp 생성
scwin.comp_init = async function () {   
	// 기존 target 있으면 삭제
    if (typeof gdl_org !== 'undefined') {
        $p.data.remove("gdl_org");
    }

    if (typeof target1 !== 'undefined') {
        $p.data.remove("target1");
    }

    if (typeof gridView1 !== 'undefined') {
        gridView1.remove();
    }   

    if (typeof gridView2 !== 'undefined') {
        gridView2.remove();
    }    

    // // 조건 설정       
    // let properties = {

    // };

    // let cList = $c.gcm.createCList(properties);

    // // 이벤트 설정
    // let eList = $c.gcm.createEList([""]);       

	// target 생성
    $c.gcm.createOrginalDataList('rowNumData="true"');
    $c.gcm.createBasicLinkedDataList();

    // gridView 생성
    $c.gcm.createOriginalGridView();
    $c.gcm.createLinkedGridView();
}   



scwin.btn_getAllFilteredJSON_onclick = function (e) {
    let rtn = target1.getAllFilteredJSON();
    let jsonString = JSON.stringify(rtn);

	wf_body_bottom.getObj("scwin").setReturnValue("result: " + rtn);
	wf_body_bottom.getObj("scwin").setReturnValue("result.json: " + jsonString);
};



scwin.btn_setColumnFilter_onclick = function (e) {
	target1.setColumnFilter({type:"row", colIndex:"cat2", key:"A1", condition:"and"});
};



scwin.btn_org_setColumnFilter_onclick = function (e) {
	gdl_org.setColumnFilter({type:"row", colIndex:"value", key:"AA11", condition:"and"});
    gdl_org.setColumnFilter({type:"row", colIndex:"value", key:"AA21", condition:"or"});
    gdl_org.setColumnFilter({type:"row", colIndex:"value", key:"BB11", condition:"or"});
    gdl_org.setColumnFilter({type:"row", colIndex:"value", key:"BB21", condition:"or"});
};
